def article_html(item, canonical):
    faq_schema = [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in item["faq"]]
    schema = {
        "@context": "https://schema.org",
        "@graph": [
            {"@type": "Article", "headline": item["title"], "description": item["description"], "inLanguage": "ar-KW", "author": {"@type": "Organization", "name": "أورا للأفكار"}, "publisher": {"@type": "Organization", "name": "أورا للأفكار", "logo": {"@type": "ImageObject", "url": BASE + "/logo-512.png"}}, "mainEntityOfPage": {"@type": "WebPage", "@id": canonical}},
            {"@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "الرئيسية", "item": BASE + "/"}, {"@type": "ListItem", "position": 2, "name": "المدونة", "item": BASE + "/المدونة/"}, {"@type": "ListItem", "position": 3, "name": item["title"], "item": canonical}]},
            {"@type": "FAQPage", "mainEntity": faq_schema}
        ]
    }
    parts = [f'<main class="article-page" dir="rtl"><div class="article-breadcrumb"><a href="/">الرئيسية</a> ← <a href="/المدونة/">المدونة</a> ← {escape(item["category"])}</div><h1>{escape(item["title"])}</h1><p class="article-lead">{escape(item["intro"])}</p><article class="article-content container">']
    parts.append(f'<p>يقدم هذا الدليل خلاصة عملية حول <strong>{escape(item["keyword"])}</strong>، مع خطوات قابلة للتطبيق وملاحظات تساعد الطالب والباحث في الكويت والخليج على تنظيم العمل الأكاديمي.</p>')
    for heading, p1, p2 in item["sections"]:
        parts.append(f'<section><h2>{escape(heading)}</h2><p>{escape(p1)}</p><p>{escape(p2)}</p></section>')
    parts.append('<section><h2>أسئلة شائعة</h2>')
    for q, a in item["faq"]:
        parts.append(f'<h3>{escape(q)}</h3><p>{escape(a)}</p>')
    parts.append(f'</section><section class="aura-article-conclusion"><h2>الخلاصة</h2><p>{escape(item["title"])} موضوع يحتاج إلى وضوح في الهدف واتساق في الخطوات ومراجعة قبل التسليم. ابدأ بتحديد المطلوب، ثم نفّذ كل مرحلة على أساس دليل الجامعة وملاحظات المشرف.</p><p>تذكّر أن الجودة الأكاديمية لا تقاس بكثرة الصفحات أو الوعود السريعة، بل بسلامة السؤال والمنهج ودقة التوثيق وقدرتك على تفسير ما قدمته الدراسة. ويمكنك الرجوع إلى <a href="/المدونة/">مقالات المدونة</a> و<a href="/خدماتنا/">الخدمات الأكاديمية</a> لمزيد من الإرشادات.</p></section></article><script type="application/ld+json">{json.dumps(schema, ensure_ascii=False)}</script></main>')
    return ''.join(parts)


def update_document(item):
    slug = item["slug"]
    out_dir = ROOT / slug
    out_dir.mkdir(parents=True, exist_ok=True)
    canonical = f"{BASE}/{slug}/"
    soup = BeautifulSoup(TEMPLATE.read_text(encoding="utf-8"), "html.parser")
    soup.title.string = f'{item["title"]} | أورا للأفكار في الكويت'
    for meta in soup.find_all("meta"):
        if meta.get("name") == "description":
            meta["content"] = item["description"]
        if meta.get("name") == "keywords":
            meta["content"] = f'{item["keyword"]}, أبحاث جامعية، خدمات أكاديمية في الكويت، {item["category"]}'
        if meta.get("property") == "og:title":
            meta["content"] = item["title"]
        if meta.get("property") == "og:description":
            meta["content"] = item["description"]
        if meta.get("property") == "og:url":
            meta["content"] = canonical
        if meta.get("name") == "twitter:title":
            meta["content"] = item["title"]
        if meta.get("name") == "twitter:description":
            meta["content"] = item["description"]
    canon = soup.find("link", rel=lambda v: v and "canonical" in v)
    if canon:
        canon["href"] = canonical
    robots = soup.find("meta", attrs={"name": "robots"})
    if robots:
        robots["content"] = "index,follow,max-image-preview:large"
    main = soup.find("main")
    main_html = BeautifulSoup(article_html(item, canonical), "html.parser")
    main.replace_with(main_html.find("main"))
    (out_dir / "index.html").write_text(str(soup), encoding="utf-8")


def update_blog():
    soup = BeautifulSoup(BLOG.read_text(encoding="utf-8"), "html.parser")
    posts = soup.find(id="posts")
    if not posts:
        raise RuntimeError("blog posts container not found")
    existing = {a.get("href") for a in posts.find_all("a", href=True)}
    for item in articles:
        href = f'/{item["slug"]}/'
        if href in existing:
            continue
        card = soup.new_tag("article", attrs={"class": "post-card", "data-category": item["category"], "data-search": f'{item["title"]} {item["keyword"]}'})
        icon = soup.new_tag("div", attrs={"class": "post-icon", "aria-hidden": "true"}); icon.string = "✦"
        body = soup.new_tag("div", attrs={"class": "post-body"})
        kicker = soup.new_tag("span", attrs={"class": "post-kicker"}); kicker.string = item["category"]
        h2 = soup.new_tag("h2"); link = soup.new_tag("a", href=href); link.string = item["title"]; h2.append(link)
        p = soup.new_tag("p"); p.string = item["description"]
        read = soup.new_tag("a", attrs={"class": "read-more", "href": href}); read.append("اقرأ المقال "); span = soup.new_tag("span"); span.string = "←"; read.append(span)
        for node in (kicker, h2, p, read): body.append(node)
        card.append(icon); card.append(body); posts.append(card)
    text = str(soup)
    text = text.replace("230 مقالًا ودليلًا", "241 مقالًا ودليلًا").replace("230+", "241+")
    BLOG.write_text(text, encoding="utf-8")


for item in articles:
    update_document(item)
update_blog()
print(f"created {len(articles)} articles")
print("slugs:", ", ".join(item["slug"] for item in articles))

def check():
    for item in articles:
        p = ROOT / item["slug"] / "index.html"
        assert p.exists() and p.stat().st_size > 10000, p
        txt = p.read_text(encoding="utf-8")
        assert item["title"] in txt and 'application/ld+json' in txt and 'rel="canonical"' in txt, p
    print("article checks passed")
check()
